        if self.services.capacity() > limits.project_services.min(CEILINGS.project_services) { return Err(Problem { path: Path::ProjectServices, reason: skein_codec::Reason::Bound }); }
        for item_0 in self.services.as_slice() {
        item_0.check(limits)?;
        }
        if self.recurring.len() > usize::try_from(limits.project_recurring.min(CEILINGS.project_recurring)).expect("u32 fits usize") { return Err(Problem { path: Path::ProjectRecurring, reason: skein_codec::Reason::Bound }); }
