impl ObjectKey {
    /// Measures this variant's wire encoding.
    #[must_use]
    pub fn measure(&self) -> u32 {
        match self {
            Self::Task(record) => 1_u32.checked_add(ObjectKeyTask::measure(record)).expect("schema ceilings fit u32"),
            Self::Proposal(record) => 1_u32.checked_add(ObjectKeyProposal::measure(record)).expect("schema ceilings fit u32"),
            Self::Escalation(record) => 1_u32.checked_add(ObjectKeyEscalation::measure(record)).expect("schema ceilings fit u32"),
            Self::Question(record) => 1_u32.checked_add(ObjectKeyQuestion::measure(record)).expect("schema ceilings fit u32"),
            Self::PersonTask(record) => 1_u32.checked_add(ObjectKeyPersonTask::measure(record)).expect("schema ceilings fit u32"),
            Self::Result(record) => 1_u32.checked_add(ObjectKeyResult::measure(record)).expect("schema ceilings fit u32"),
            Self::Note(record) => 1_u32.checked_add(ObjectKeyNote::measure(record)).expect("schema ceilings fit u32"),
        }
    }

    /// Writes this variant's tag and payload.
    pub fn encode(&self, writer: &mut skein_lib::Writer) -> Result<(), skein_lib::Overflow> {
        match self {
            Self::Task(record) => { writer.put(&[0_u8])?; record.encode(writer)?; }
            Self::Proposal(record) => { writer.put(&[1_u8])?; record.encode(writer)?; }
            Self::Escalation(record) => { writer.put(&[2_u8])?; record.encode(writer)?; }
            Self::Question(record) => { writer.put(&[3_u8])?; record.encode(writer)?; }
            Self::PersonTask(record) => { writer.put(&[4_u8])?; record.encode(writer)?; }
            Self::Result(record) => { writer.put(&[5_u8])?; record.encode(writer)?; }
            Self::Note(record) => { writer.put(&[6_u8])?; record.encode(writer)?; }
        }
        Ok(())
    }

    /// Reads a whole variant and refuses trailing bytes.
    pub fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::decode_from(limits, reader)?;
        if !reader.is_empty() { return Err(Problem { path: Path::ObjectKeyTag, reason: skein_codec::Reason::Trailing }); }
        Ok(value)
    }

    fn decode_from(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: Path::ObjectKeyTag, reason: skein_codec::Reason::Short })?;
        let value = match tag {
            0 => Self::Task(ObjectKeyTask::decode_from(limits, reader)?),
            1 => Self::Proposal(ObjectKeyProposal::decode_from(limits, reader)?),
            2 => Self::Escalation(ObjectKeyEscalation::decode_from(limits, reader)?),
            3 => Self::Question(ObjectKeyQuestion::decode_from(limits, reader)?),
            4 => Self::PersonTask(ObjectKeyPersonTask::decode_from(limits, reader)?),
            5 => Self::Result(ObjectKeyResult::decode_from(limits, reader)?),
            6 => Self::Note(ObjectKeyNote::decode_from(limits, reader)?),
            _ => return Err(Problem { path: Path::ObjectKeyTag, reason: skein_codec::Reason::Tag }),
        };
        Ok(value)
    }
}

