        heap = heap.checked_add(ModelSet::worst_case_heap_within(limits)?)?.checked_add(0_u64)?;
        heap = heap.checked_add(u64::from(limits.authority_grants))?.checked_add(List::<Executor>::worst_case(limits.authority_task_kinds)?.checked_add(u64::from(limits.authority_task_kinds).checked_mul(Executor::worst_case_heap_within(limits)?)?)?)?;
        heap = heap.checked_add(0_u64)?.checked_add(0_u64)?;
        heap = heap.checked_add(0_u64)?.checked_add(List::<u16>::worst_case(limits.authority_tools)?.checked_add(u64::from(limits.authority_tools).checked_mul(0_u64)?)?)?;
