/// Maximum heap held by one decoded top-level value.
#[must_use]
pub fn worst_case_heap(limits: &Limits) -> Option<u64> {
    if check_limits(limits).is_err() { return None; }
    let mut biggest = 0_u64;
    biggest = worst_case_heap_0(limits, biggest)?;
    biggest = worst_case_heap_1(limits, biggest)?;
    biggest = worst_case_heap_2(limits, biggest)?;
    biggest = worst_case_heap_3(limits, biggest)?;
    biggest = worst_case_heap_4(limits, biggest)?;
    biggest = worst_case_heap_5(limits, biggest)?;
    biggest = worst_case_heap_6(limits, biggest)?;
    biggest = worst_case_heap_7(limits, biggest)?;
    biggest = worst_case_heap_8(limits, biggest)?;
    biggest = worst_case_heap_9(limits, biggest)?;
    biggest = worst_case_heap_10(limits, biggest)?;
    biggest = worst_case_heap_11(limits, biggest)?;
    Some(biggest)
}

